struct Sphere
{
    vec3 origin;
    vec3 color;
    float radius;
};

float sphereDistance(Sphere sphere, vec3 pos)
{
    return length(pos - sphere.origin) - sphere.radius;
}

vec3 sphereNormal(Sphere sphere, vec3 pos)
{
    return normalize(pos - sphere.origin);
}

float rayMarch(out vec3 currentRayPos, vec3 rayDir, Sphere sphere)
{

    float dist = sphereDistance(sphere, currentRayPos);
    currentRayPos += rayDir * dist;
    return dist;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float distThreshold = 0.01;
    float rayLengthThreshold = 1000.0;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord/iResolution.xy * 2.0) - 1.0;
    uv.x *= iResolution.x / iResolution.y;


    //initialize ray
    float rayLength = 0.0;
    vec3 rayOrigin = vec3(0.0, 0.0, -11.5);
    vec3 cameraPos = vec3(uv, -10.0);
    vec3 currentRayPos = cameraPos;
    vec3 rayDir = normalize(cameraPos - rayOrigin);

    Sphere test = Sphere(vec3(0.0), vec3(1.0, 1.0, 0.0), 2.0);
    float dist = rayMarch(currentRayPos, rayDir, test);

    while(dist > distThreshold && rayLength < rayLengthThreshold)
    {
        dist = rayMarch(currentRayPos, rayDir, test);
        rayLength += dist;
    }

    vec3 color = vec3(0.0);


    if(dist <= distThreshold)
    {
        color = vec3(test.color);
        float colorMultiplier = dot(sphereNormal(test, currentRayPos), normalize(vec3(0.5, cos(iTime), sin(iTime))));
        colorMultiplier *= colorMultiplier * colorMultiplier;
        color *= colorMultiplier;
    }

    // Output to screen
    fragColor = vec4(color, 1.0);
}
